-- DROP in a comment is fine
CREATE TABLE IF NOT EXISTS a (id int);
CREATE UNIQUE INDEX IF NOT EXISTS ix ON a (id);
/* DROP in a block comment */
ALTER TABLE a ADD COLUMN IF NOT EXISTS b int, ADD COLUMN IF NOT EXISTS c text DEFAULT 'x;DROP';
DO $$ BEGIN IF NOT EXISTS (SELECT 1) THEN ALTER TABLE a ADD COLUMN d int; END IF; END $$;
